// Java example
class Car {
  String brand;
  int speed;
  Car(String b, int s) { brand = b; speed = s; }
  void display() { System.out.println(brand + " @ " + speed + "kmph"); }
}
public class Main {
  public static void main(String[] args) {
    Car c = new Car("Tesla", 200);
    c.display();
  }
}
